const results = await Promise.allSettled([
  tools.exec_command({cmd:"find .. -name AGENTS.md -print",workdir:"/app",yield_time_ms:10000,max_output_tokens:3000}),
  tools.exec_command({cmd:"git status --short",workdir:"/app",yield_time_ms:10000,max_output_tokens:3000}),
  tools.exec_command({cmd:"find . -maxdepth 2 -type f | head -100",workdir:"/app",yield_time_ms:10000,max_output_tokens:5000}),
  tools.exec_command({cmd:"find .codex-role-output -maxdepth 2 -type f -print",workdir:"/app",yield_time_ms:10000,max_output_tokens:2000})
]); results.forEach((r,i)=>text(JSON.stringify({i,status:r.status,result:r.status==="fulfilled"?r.value.output:String(r.reason)})));

const results=await Promise.allSettled([
  tools.exec_command({cmd:"grep -R \"\\.Find(\" -n --include='*.go' .",workdir:"/app",yield_time_ms:10000,max_output_tokens:8000}),
  tools.exec_command({cmd:"grep -R \"LibraryFixedIn\\|LibraryScanners\\|convertLibWithScanner\\|scanLibraries\\|getVulnDetail\\|FillLibrary\\|AnalyzeFile\" -n --include='*.go' .",workdir:"/app",yield_time_ms:10000,max_output_tokens:12000}),
  tools.exec_command({cmd:"cat go.mod",workdir:"/app",yield_time_ms:10000,max_output_tokens:5000})
]); results.forEach((r,i)=>text(JSON.stringify({i,status:r.status,result:r.status==="fulfilled"?r.value.output:String(r.reason)})));

