package libmanager

import (
	"testing"

	"github.com/future-architect/vuls/models"
)

func TestMergeLibraryVulnerabilityPreservesSources(t *testing.T) {
	result := &models.ScanResult{
		ScannedCves: models.VulnInfos{
			"CVE-2020-0001": {
				CveID: "CVE-2020-0001",
				AffectedPackages: models.PackageFixStatuses{
					{Name: "system-package"},
				},
				CveContents: models.CveContents{
					models.Nvd: {Type: models.Nvd, Summary: "OS advisory"},
				},
			},
		},
	}

	mergeLibraryVulnerability(result, models.VulnInfo{
		CveID: "CVE-2020-0001",
		CveContents: models.CveContents{
			models.Trivy: {Type: models.Trivy, Summary: "Library advisory"},
		},
		LibraryFixedIns: models.LibraryFixedIns{
			{Path: "/app/one/Pipfile.lock", Name: "requests", FixedIn: "2.20.0"},
		},
	})
	mergeLibraryVulnerability(result, models.VulnInfo{
		CveID: "CVE-2020-0001",
		LibraryFixedIns: models.LibraryFixedIns{
			{Path: "/app/two/Pipfile.lock", Name: "requests", FixedIn: "2.21.0"},
		},
	})

	got := result.ScannedCves["CVE-2020-0001"]
	if len(got.LibraryFixedIns) != 2 ||
		got.LibraryFixedIns[0].Path != "/app/one/Pipfile.lock" ||
		got.LibraryFixedIns[1].Path != "/app/two/Pipfile.lock" {
		t.Fatalf("library sources were not retained: %#v", got.LibraryFixedIns)
	}
	if len(got.AffectedPackages) != 1 || got.AffectedPackages[0].Name != "system-package" {
		t.Errorf("existing package finding was lost: %#v", got.AffectedPackages)
	}
	if _, ok := got.CveContents[models.Nvd]; !ok {
		t.Error("existing NVD content was lost")
	}
	if _, ok := got.CveContents[models.Trivy]; !ok {
		t.Error("Trivy content was not added")
	}
	if len(got.Confidences) != 1 || got.Confidences[0].DetectionMethod != models.TrivyMatch.DetectionMethod {
		t.Errorf("Trivy confidence should appear once: %#v", got.Confidences)
	}
}

